    // Registro modular de ventanas para los botones de la herramienta
    const TOOL_WINDOWS = {
        home: { title: 'Terminal Home & Node.js', handler: () => showTerminalView() },
        search: { title: 'Búsqueda Global en Archivos', handler: (id) => showPlaceholderTool(id, 'Búsqueda Global') },
        warpAi: { title: 'Warp AI Engine & Generador', handler: (id) => showPlaceholderTool(id, 'Warp AI Engine') },
        notebook: { title: 'Cuaderno Interactivo & Markdown', handler: (id) => showPlaceholderTool(id, 'Notebook Interactivo') },
        accordion: { title: 'Estructura & Árbol de Código', handler: (id) => showPlaceholderTool(id, 'Estructura de Carpetas') },
        saxophone: { title: 'Audio & Procesamiento DSP', handler: (id) => showPlaceholderTool(id, 'Audio & DSP Toolkit') },
        plane: { title: 'Deploy & Despliegue Cloud', handler: (id) => showPlaceholderTool(id, 'Cloud Deployment') },
        airplane: { title: 'Rutas & API Gateway', handler: (id) => showPlaceholderTool(id, 'API Gateway Routing') },
        potion: { title: 'Compilador & WebAssembly', handler: (id) => showPlaceholderTool(id, 'WASM Compiler') },
        dragon: { title: 'Motor de Inteligencia & Agentes', handler: (id) => showPlaceholderTool(id, 'Engine AI Core') },
        tractor: { title: 'Procesamiento Masivo de Datos', handler: (id) => showPlaceholderTool(id, 'Data Pipeline') },
        settings: { title: 'Configuración & Preferencias', handler: (id) => showPlaceholderTool(id, 'Ajustes de Terminal') }
    };

    let activeToolId = 'home';
    let tabs = [
        { id: 'tab-1', title: 'bash', icon: 'bash', feed: [], history: [], cwd: '~/workspace' }
    ];
    let activeTabId = 'tab-1';
    let tabCounter = 1;
    let historyIndex = -1;

    function getActiveTab() {
        return tabs.find(t => t.id === activeTabId) || tabs[0];
    }

    const WarpTerminal = {
        open() {
            const modal = document.getElementById('tool3Modal') || document.getElementById('warpTerminalModal');
            if (modal) {
                modal.classList.add('open');
                renderTabs();
                renderActiveFeed();
                setTimeout(() => {
                    const inp = modal.querySelector('#warpCmdInput') || document.getElementById('warpCmdInput');
                    if (inp) inp.focus();
                }, 100);
            }
        },

        close() {
            const modal1 = document.getElementById('tool3Modal');
            if (modal1) modal1.classList.remove('open');
            const modal2 = document.getElementById('warpTerminalModal');
            if (modal2) modal2.classList.remove('open');
        },

        registerToolWindow(toolId, config) {
            TOOL_WINDOWS[toolId] = config;
        },

        async executeCommand(cmd) {
            if (!cmd || !cmd.trim()) return;
            const command = cmd.trim();
            const curTab = getActiveTab();
            curTab.history.push(command);
            historyIndex = curTab.history.length;

            const feed = document.getElementById('warpTerminalFeed');
            const placeholder = document.getElementById('warpAmbientPlaceholder');
            if (placeholder) placeholder.classList.add('hidden');

            const block = document.createElement('div');
            block.className = 'warp-cmd-block';
            block.innerHTML = `
                <div class="warp-cmd-line">
                    <span class="prompt-symbol">&gt;</span>
                    <span>${escapeHtml(command)}</span>
                </div>
                <div class="warp-cmd-output" style="color: #94a3b8;">Ejecutando en Bash 4.3...</div>
            `;
            if (feed) feed.appendChild(block);
            scrollFeedToBottom();

            try {
                const res = await fetch(l8ApiUrl('api/bash/exec'), {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ command: command })
                });
                const data = await res.json();
                const outputEl = block.querySelector('.warp-cmd-output');

                const outputText = data.ok ? (data.stdout || '(Comando ejecutado sin salida)') : (data.stderr || data.error || 'Error en ejecución');
                const isOk = !!data.ok;

                outputEl.textContent = outputText;
                outputEl.style.color = isOk ? '#E2E8F0' : '#EF4444';

                // Guardar en el feed persistente de la pestaña activa
                curTab.feed.push({
                    command: command,
                    output: outputText,
                    ok: isOk,
                    time: Date.now()
                });
            } catch (e) {
                const outputEl = block.querySelector('.warp-cmd-output');
                const errText = 'Error de conexión: ' + e.message;
                outputEl.textContent = errText;
                outputEl.style.color = '#EF4444';
                curTab.feed.push({
                    command: command,
                    output: errText,
                    ok: false,
                    time: Date.now()
                });
            }
            scrollFeedToBottom();
        }
    };

    function renderTabs() {
        const containers = document.querySelectorAll('.warp-tabs-container');
        containers.forEach(container => {
            container.innerHTML = '';
            tabs.forEach(tab => {
                const isActive = tab.id === activeTabId;
                const tabEl = document.createElement('div');
                tabEl.className = 'warp-tab-item' + (isActive ? ' active' : '');
                tabEl.setAttribute('data-tab-id', tab.id);
                tabEl.title = tab.title;
                tabEl.onclick = () => window.selectWarpTab(tab.id);
                tabEl.innerHTML = `
                    <span class="warp-tab-icon">${SVG_ICONS[tab.icon] || SVG_ICONS.nodejs}</span>
                    <span class="warp-tab-title">${escapeHtml(tab.title)}</span>
                    <button type="button" class="warp-tab-close" title="Cerrar pestaña" onclick="window.closeWarpTab('${tab.id}', event)">&times;</button>
                `;
                container.appendChild(tabEl);
            });

            const addBtn = document.createElement('button');
            addBtn.type = 'button';
            addBtn.className = 'warp-add-tab-btn';
            addBtn.id = 'warpAddTabBtn';
            addBtn.title = 'Nueva pestaña';
            addBtn.textContent = '+';
            addBtn.onclick = (e) => {
                e.stopPropagation();
                window.createWarpTab();
            };
            container.appendChild(addBtn);
        });
    }

    window.createWarpTab = function (title) {
        tabCounter++;
        const newId = 'tab-' + tabCounter;
        const defaultNames = ['bash', 'node.js', 'bash 2', 'node.js 2', 'bash 3', 'node.js 3'];
        const tabTitle = title || (defaultNames[tabCounter - 1] || ('bash ' + tabCounter));
        tabs.push({
            id: newId,
            title: tabTitle,
            icon: 'nodejs',
            feed: [],
            history: [],
            cwd: '~/workspace'
        });
        window.selectWarpTab(newId);
    };

    window.selectWarpTab = function (tabId) {
        activeTabId = tabId;
        renderTabs();
        renderActiveFeed();
        const tab = getActiveTab();
        historyIndex = tab.history.length;
        const pathEl = document.getElementById('warpStatusPath');
        if (pathEl) pathEl.textContent = tab.cwd || '~/workspace';
        const inp = document.getElementById('warpCmdInput');
        if (inp) {
            inp.value = '';
            inp.focus();
        }
    };

    window.closeWarpTab = function (tabId, event) {
        if (event) event.stopPropagation();
        const index = tabs.findIndex(t => t.id === tabId);
        if (index === -1) return;
        tabs.splice(index, 1);
        if (tabs.length === 0) {
            tabCounter = 1;
            const newId = 'tab-1';
            tabs.push({
                id: newId,
                title: 'bash',
                icon: 'nodejs',
                feed: [],
                history: [],
                cwd: '~/workspace'
            });
            activeTabId = newId;
        } else if (activeTabId === tabId) {
            activeTabId = tabs[Math.max(0, index - 1)].id;
        }
        renderTabs();
        renderActiveFeed();
    };

    function renderActiveFeed() {
        const tab = getActiveTab();
        const feed = document.getElementById('warpTerminalFeed');
        const placeholder = document.getElementById('warpAmbientPlaceholder');
        if (!feed) return;
        feed.innerHTML = '';
        if (tab.feed && tab.feed.length > 0) {
            if (placeholder) placeholder.classList.add('hidden');
            tab.feed.forEach(item => {
                const block = document.createElement('div');
                block.className = 'warp-cmd-block';
                block.innerHTML = `
                    <div class="warp-cmd-line">
                        <span class="prompt-symbol">&gt;</span>
                        <span>${escapeHtml(item.command)}</span>
                    </div>
                    <div class="warp-cmd-output" style="color:${item.ok ? '#E2E8F0' : '#EF4444'}; white-space:pre-wrap; font-family:'Geist Mono', 'IBM Plex Mono', monospace;">${escapeHtml(item.output)}</div>
                `;
                feed.appendChild(block);
            });
        } else {
            if (placeholder) placeholder.classList.remove('hidden');
        }
        scrollFeedToBottom();
    }

